-- BACKUP: bak_20261026_paper_learnings
-- PAPER-LEARN-SESSION-TRIAGE-1 (2026-10-26, charter pillar: autonomy; agent_issues 100311, 100319, 100325, 100338, 100353, successor 1000459).
-- Read 2026-10-26: the five oldest open PAPER-LEARN-1 issues each wait for every direct learning of their paper to leave 'proposed'. Their 21 learnings were each marked 'apply' by ONE model on
-- 2026-10-20 (PL-TRIAGE-1 apply: a single model saying gap does not settle a row, so the hourly triage never touches them again and no doer existed). A session read each learning against the
-- repository and qnfo-audit, as the issue text instructs (a learning is a lead, not a fact), and settled it:
--   already-in-place  646 (research ready cap and deferred pool), 696 (remedy_efficacy_30d, fix_hold_rate_30d), 847 (decision_log predictions and outcome_matched, fix_hold_rate_30d);
--   rejected          644 and 645 (retries are correlated: tasks that needed a 4th attempt merged 24 of 89, a 7th 4 of 40), 647, 650 (premise contradicted by $299.84 per 30 days), 697, 700, 701, 703,
--                     774, 776, 940 (the paper's own convention; a hard gate on a keyword proxy, the same ruling as learnings 17, 47 and 48 on 2026-10-20), 848, 849, 850, 851, 852;
--   routed            698 -> agent_issues 1000459 TRIGGER-FLAP-1 (167 reopens on 44 METRIC-TRIGGER tickets in 7 days), 699 -> agent_issues 1000043 (cf_analytics under-reports spend 7.4x).
-- A rejected learning names why and what evidence would reopen it; an in-place one names the mechanism and a probe that read ok today; a routed one names the successor issue that owns it. No learning was
-- applied: none of the 21 named a change that was both sound and absent. This file also adds three catalogue mechanisms (no auto-match terms except one narrow one) so the hourly triage can cite them.
-- Revert one row: UPDATE paper_learnings SET fleet_status = 'proposed', status_note = NULL WHERE id = <id>.
CREATE TABLE IF NOT EXISTS bak_20261026_paper_learnings AS SELECT * FROM paper_learnings WHERE id IN (644, 645, 646, 647, 650, 696, 697, 698, 699, 700, 701, 703, 774, 776, 847, 848, 849, 850, 851, 852, 940);

CREATE TABLE IF NOT EXISTS paper_learning_mechanisms (mech_key TEXT PRIMARY KEY, title TEXT NOT NULL, terms TEXT NOT NULL DEFAULT '', citation TEXT NOT NULL, evidence_probe TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')));

INSERT OR REPLACE INTO paper_learning_mechanisms (mech_key, title, terms, citation, evidence_probe) VALUES
  ('research-backpressure', 'RESEARCH-BACKPRESSURE-1 bounds the ready queue of qnfo-research-exec and parks the surplus in a visible deferred pool', 'research_ready_cap|ready queue cap', 'RESEARCH-BACKPRESSURE-1 (qnfo-fleet-control 0.24.0): ops_config research_ready_cap bounds the research ready queue, the surplus waits in a deferred pool measured by research_deferred_pool, and research-backpressure events record each tick', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM ops_config WHERE key = ''research_ready_cap'') AND EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''research-backpressure'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-1 day'')) THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('remedy-efficacy', 'remedy_efficacy_30d and fix_hold_rate_30d measure whether a remedy moved its metric and whether a closure held', '', 'the metric_registry rows remedy_efficacy_30d and fix_hold_rate_30d, refreshed hourly from the fleet''s own remedy outcomes; CORE-PROMPT-1 rule 6 replaces a remedy that did not move its metric in 7 days', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''remedy_efficacy_30d'' AND last_refreshed >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 hours'')) AND EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''fix_hold_rate_30d'' AND last_refreshed >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 hours'')) THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('forward-outcome-scoring', 'decision_log records a predicted outcome before the result and outcome_matched after it; prediction_miss_rate_7d grades the loop on outcomes it did not choose', '', 'decision_log.predicted_outcome and outcome_matched (DOCTRINE revision 4 section 22), graded by the metrics prediction_logged_share_7d and prediction_miss_rate_7d; fix_hold_rate_30d judges each closure against later metric days', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''prediction_logged_share_7d'' AND last_refreshed >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 hours'')) AND EXISTS (SELECT 1 FROM decision_log WHERE outcome_matched IS NOT NULL) THEN ''ok'' ELSE ''absent'' END AS observed');

UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; conflicts with measured retry data): the formula 1-(1-p)^(r+1) assumes independent attempts at a constant p. The fleet''s own code_tasks created since 2026-10-12 show attempts are correlated: of tasks that ended merged or failed after 4 or more attempts only 24 of 89 (27%) merged, after 7 or more only 4 of 40 (10%), because a retry meets the same failure. NO-PROGRESS-CEILING-1 already stops retrying when no new failure signature appears. Re-propose with a retry budget conditioned on a new failure signature.'
WHERE id = 644 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; conflicts with budget-steering-eval): BUDGET-SOFT-ROUTE-1 pairs a downgrade to a cheaper model with a per-request fallback to the previous model and an automatic revert on errors or empty replies (OWNER-STANDING-GRANT-1, TWIN-FLASH-1 pattern), and qnfo-model-eval keeps the A/B record (probe ok 2026-10-26). More retries of the same weaker model do not compound here: retries are correlated (see learning 644).'
WHERE id = 645 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'already-in-place', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 in place (session-old-issues-6d-2038, 2026-10-26): research-backpressure - RESEARCH-BACKPRESSURE-1 (qnfo-fleet-control 0.24.0) is the screening-ratio lever the learning names: ops_config research_ready_cap = 192 bounds the ready queue of qnfo-research-exec, the surplus waits in a visible deferred pool (metric research_deferred_pool, 240 on 2026-10-26, with its own trigger), 33 research-backpressure events in 24 h (probe ok 2026-10-26). The paper''s token arithmetic is for omics retrieval; the fleet measures neurons per publication directly.'
WHERE id = 646 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; conflicts with ensemble-review): ENSEMBLE-POLICY-1 sizes the fleet''s ensembles by error correlation, not by token price: a 9-judge, 7-family panel is worth about 2.2 independent votes, so majority voting over m sources does not buy the independence the paper''s arithmetic assumes; layers stay few and small and use the cheapest models while a cap is breached (probe ok 2026-10-26: revise-patch and review-unresolved events in 3 days).'
WHERE id = 647 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; premise contradicted by live measurement): Workers AI cost over 30 days reads $299.84 against a $95 trigger and the all-billing monthly run rate $1,466.84 against 650 (metric_registry 2026-10-26), and qnfo-research-exec spent 59,589 neurons per publication over 7 days (measured 2026-10-24); token budgeting is not financially negligible at the fleet''s volume. The cited per-token benchmark rate is also unchecked.'
WHERE id = 650 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'already-in-place', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 in place (session-old-issues-6d-2038, 2026-10-26): remedy-efficacy - the action tallies the paper derives alpha from are measured by the fleet itself: remedy_efficacy_30d (0.6 at 2026-10-26T17:00Z, hourly) and fix_hold_rate_30d (0.4884) are computed from remedy outcomes, not assumed (probe ok 2026-10-26); the learn-apply-verify loop of CORE-PROMPT-1 rule 6 replaces a remedy that did not move its metric in 7 days.'
WHERE id = 696 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; analogy-only): the claim is a property of the paper''s own linear model E[F] = N_w * p_f * (1 - alpha); it names no fleet quantity to change, and the fleet does not run that model: its failure signals are per event (canary, contracts, failure_modes) and per metric trigger. Re-propose with a fleet metric whose sensitivity to a per-worker failure probability was measured.'
WHERE id = 697 AND fleet_status = 'proposed' AND applicability = 'direct';
