  status_note = 'PL-TRIAGE-1 routed (session-old-issues-6d-2038, 2026-10-26): routed to issue 1000043 (open, code task queued): cf_analytics under-reports Workers AI 30d cost by 7.4x ($37.76 against $288.60), the same class of defect as the paper''s cents-as-dollars misread: a spend feed read without a cross-check. That issue now carries this learning, so its fix owns the feed cross-check and unit check. This learning is closed against it, not by it.'
WHERE id = 699 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; numbers superseded; the lever is a recorded decision): the paper''s $90 per-30-days gate is obsolete (Workers AI cost reads $299.84 per 30 days against a $95 trigger, breached without any unit error). Caps steer model choice and never stop work (BUDGET-SOFT-ROUTE-1) and change only by a recorded fleet_budget migration (RULE-8-RETIRED-1), so recalibrating a gate from a paper''s figure is not a fleet change.'
WHERE id = 700 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; analogy-only): the +/-0.5 failure band is the refutation threshold of the paper''s own model (E[F] = 2.16 failures a month); the fleet''s falsification is per metric: a trigger with a threshold, a recovery rule, and REMEDIATION-REOPEN-2 on a relapse after closure. No fleet quantity is named.'
WHERE id = 701 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; analogy-only): independence of per-worker failures is an assumption of the paper''s binomial model, which the fleet uses for no decision. Correlated failure from a shared bad deploy is handled where it is measured: every control-plane deploy has a /health canary with automatic revert (scripts/canary_revert.py), and failure_modes_recurring flags a recurrence. Re-propose with a measured case of correlated failures those missed.'
WHERE id = 703 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; paper-convention): the ''smallest next test'' is this paper''s own research roadmap (a TRL 1-2 benchmark on a standard continuum system), not a fleet mechanism. It is a research task, and the research queue already holds 418 accepted ideas of which 404 are over their 120-minute stage SLA (v_content_stage_summary 2026-10-26), so a task adds backlog without changing a loop. Re-propose as a research idea through research_queue.'
WHERE id = 774 AND fleet_status = 'proposed' AND applicability = 'direct';
