  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; analogy-only): the 10x and 5x Gaussian-process emulation reductions are cited-unchecked third-party figures for expensive simulators; the fleet has no simulation-budget workload (its compute is LLM calls and D1 queries), and adaptive allocation of AI spend is steered by BUDGET-SOFT-ROUTE-1 and the research ready cap. No fleet gap is shown.'
WHERE id = 850 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; conflicts with existing guards): gaming a metric is a real risk and the fleet guards it: 118 guard metrics (kind = guard, e.g. issue_wontfix_share_7d, remediation_latest_pass_pct_7d) make a gain in a target metric with a worse guard count as a regression (INTEGRITY-GUARDS-1), and OUTPUT-QUALITY-LEDGER-1 compares the same items over time. The paper''s prior-reporting safeguard has no analogue because the fleet''s scores have no prior.'
WHERE id = 851 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; analogy-only): ensemble results in the fleet are verdicts (pass, reject, unresolved) from disjoint model families compared by agreement, not prior-dependent likelihood scores, so re-scoring under perturbed priors has no object; the sensitivity of reviewer verdicts is measured by the guard metric seeded_false_claim_catch_rate.'
WHERE id = 852 AND fleet_status = 'proposed' AND applicability = 'direct';
UPDATE paper_learnings SET fleet_status = 'rejected', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  status_note = 'PL-TRIAGE-1 rejected (session-old-issues-6d-2038, 2026-10-26; paper-convention): labelling an extrapolated range as a projection is this paper''s own convention; 438 of 706 published papers (62%) already use the word, CLAIM-INTEGRITY-1 holds past-tense empirical claims (probe ok 2026-10-26) and the reviewer ensemble reads the rest. A machine-readable projection tag consumed by the review loop and the trust ledger would be a new gate with no measured defect (same reasoning as learnings 17, 47 and 48 in migrations/2026-10-20-paper-learn-triage.sql).'
WHERE id = 940 AND fleet_status = 'proposed' AND applicability = 'direct';

-- Learning 699 is closed against issue 1000043: that issue now carries it (append-only note).
UPDATE agent_issues SET description = description || char(10) || 'PAPER-LEARN-1 learning 699 (paper quniverse-fleet-lessons 1.7.0, session-old-issues-6d-2038, 2026-10-26): a monetary feed must be traceable to a source in the same unit; the paper''s cents-as-dollars misread inflated spend 73-fold, here the feed under-reads 7.4x. The fix for this issue owns a cross-check of the two spend feeds (cf_analytics against the gateway or billing figure) with a ratio guard, and the learning is closed against it.',
  updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE id = 1000043 AND status = 'open' AND instr(description, 'PAPER-LEARN-1 learning 699') = 0;

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
